import{_ as a,o as s,c as r,ah as t}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Sauvegardes","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/sauvegardes.md","filePath":"src/guide/admin/sauvegardes.md"}'),n={name:"guide/admin/sauvegardes.md"};function i(u,e,o,l,p,d){return s(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="sauvegardes" tabindex="-1">Sauvegardes <a class="header-anchor" href="#sauvegardes" aria-label="Permalink to &quot;Sauvegardes&quot;">​</a></h1><p>Une sauvegarde est une copie de tout ce que votre établissement a enregistré dans ERA : élèves, familles, notes, paiements, présences, passages à l&#39;infirmerie. Elle sert à revenir en arrière si quelque chose tourne mal.</p><p>La page s&#39;ouvre par <strong>Admin → Sauvegardes</strong>. Elle n&#39;est visible que par les administrateurs.</p><div class="info custom-block"><p class="custom-block-title">Elle n&#39;apparaît pas chez vous ?</p><p>Cette page n&#39;existe que si votre établissement est seul sur son installation. Les écoles hébergées par edPage partagent un même serveur, où une sauvegarde couvrirait les données de toutes les écoles : elle est donc faite par edPage, pas depuis votre espace.</p></div><h2 id="chaque-nuit-sans-rien-faire" tabindex="-1">Chaque nuit, sans rien faire <a class="header-anchor" href="#chaque-nuit-sans-rien-faire" aria-label="Permalink to &quot;Chaque nuit, sans rien faire&quot;">​</a></h2><p>ERA prend une sauvegarde automatique toutes les nuits. Les plus récentes sont conservées, les plus anciennes disparaissent d&#39;elles-mêmes pour ne pas saturer le serveur. Le nombre conservé est indiqué en haut de la page.</p><p>C&#39;est cette sauvegarde-là qui compte le plus : elle couvre les cas où personne n&#39;a pensé à en demander une.</p><h2 id="en-demander-une-vous-meme" tabindex="-1">En demander une vous-même <a class="header-anchor" href="#en-demander-une-vous-meme" aria-label="Permalink to &quot;En demander une vous-même&quot;">​</a></h2><p>Le bouton <strong>Sauvegarder maintenant</strong> en prend une tout de suite. C&#39;est le réflexe à avoir <strong>avant une opération délicate</strong> : préparer une nouvelle année scolaire, une réinscription en masse, une suppression importante.</p><p>La sauvegarde se prépare en arrière-plan et apparaît dans la liste dès qu&#39;elle est prête, en général en moins d&#39;une minute — la page se met à jour toute seule, inutile de la recharger.</p><p>Deux refus possibles, tous deux normaux :</p><ul><li><strong>Une sauvegarde est déjà en préparation.</strong> Attendez qu&#39;elle finisse.</li><li><strong>Une sauvegarde a été faite il y a moins de quinze minutes.</strong> Elle est encore valable : reprenez celle-là.</li></ul><h2 id="la-telecharger" tabindex="-1">La télécharger <a class="header-anchor" href="#la-telecharger" aria-label="Permalink to &quot;La télécharger&quot;">​</a></h2><p>Le lien <strong>Télécharger</strong> vous remet le fichier. ERA vous <strong>redemande votre mot de passe</strong> avant : ce fichier contient toutes les données de l&#39;établissement, et une session laissée ouverte ne suffit pas à l&#39;obtenir.</p><p>Chaque téléchargement est inscrit au journal d&#39;activité, avec qui l&#39;a fait et quand. La date du dernier téléchargement est également affichée dans la liste.</p><div class="warning custom-block"><p class="custom-block-title">Ce fichier se protège comme le reste</p><p>Une fois sur votre ordinateur, il n&#39;est plus protégé par les mots de passe d&#39;ERA. Rangez-le comme vous rangeriez le registre papier de l&#39;établissement : pas dans les téléchargements, pas sur une clé USB qui traîne, pas en pièce jointe d&#39;un courriel.</p></div><h2 id="ce-que-l-archive-contient-—-et-ne-contient-pas" tabindex="-1">Ce que l&#39;archive contient — et ne contient pas <a class="header-anchor" href="#ce-que-l-archive-contient-—-et-ne-contient-pas" aria-label="Permalink to &quot;Ce que l&#39;archive contient — et ne contient pas&quot;">​</a></h2><p>Elle contient <strong>vos données</strong> : toutes les informations saisies dans ERA.</p><p>Elle ne contient <strong>pas les clés techniques de l&#39;application</strong>, qui restent sur le serveur. C&#39;est volontaire : ces clés et vos données réunies dans un même fichier téléchargeable seraient bien plus dangereuses en cas de perte du fichier.</p><p>Conséquence pratique : si votre serveur était perdu et qu&#39;il fallait tout remonter à partir d&#39;une archive téléchargée, quelques réglages techniques seraient à refaire — notamment la double authentification, à reconfigurer par les personnes qui l&#39;utilisaient. Vos données, elles, seraient intactes.</p><h2 id="restaurer" tabindex="-1">Restaurer <a class="header-anchor" href="#restaurer" aria-label="Permalink to &quot;Restaurer&quot;">​</a></h2><p><strong>La restauration ne se fait pas depuis cette page</strong>, volontairement : on ne remplace pas une base de données pendant que l&#39;application tourne dessus, et si l&#39;opération échouait, l&#39;outil qui devrait vous prévenir serait justement celui que vous venez d&#39;interrompre.</p><p>Si vous devez revenir à une sauvegarde, contactez edPage avec la date de celle que vous voulez remettre. L&#39;opération se fait sur le serveur, site fermé le temps nécessaire.</p><h2 id="supprimer-une-sauvegarde" tabindex="-1">Supprimer une sauvegarde <a class="header-anchor" href="#supprimer-une-sauvegarde" aria-label="Permalink to &quot;Supprimer une sauvegarde&quot;">​</a></h2><p><strong>Supprimer</strong> efface l&#39;archive du serveur, définitivement. En temps normal il n&#39;y a rien à faire : les plus anciennes partent toutes seules.</p>',25)])])}const v=a(n,[["render",i]]);export{m as __pageData,v as default};
